<?php $title='New Task';require __DIR__.'/../layouts/header.php';?><div class="pagehead"><h1>New Task</h1></div><form class="panel form" method="post" action="<?=route('tasks')?>"><?=csrf_field()?><div class="form-grid"><label>Title<input name="title" required></label><label>Client<select name="client_id"><option value="">—</option><?php foreach($clients as $c):?><option value="<?=$c['id']?>"><?=e($c['full_name'])?></option><?php endforeach;?></select></label><label>Project<select name="project_id"><option value="">—</option><?php foreach($projects as $p):?><option value="<?=$p['id']?>"><?=e($p['name'])?></option><?php endforeach;?></select></label><label>Assigned user<select name="assigned_user_id"><?php foreach($users as $u):?><option value="<?=$u['id']?>"><?=e($u['full_name'])?></option><?php endforeach;?></select></label><label>Priority<select name="priority"><option>low</option><option selected>normal</option><option>high</option><option>urgent</option></select></label><label>Due at<input type="datetime-local" name="due_at"></label><label class="wide">Description<textarea name="description" rows="4"></textarea></label></div><button class="primary">Create task</button></form><?php require __DIR__.'/../layouts/footer.php';?>
